import{_ as o,a0 as m,w as p,s,ao as n,I as i,x as t,a1 as a,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何在Linux上安装Telegram Messenger应用 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux上安装Telegram Messenger应用 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux上安装Telegram Messenger应用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux上安装Telegram Messenger应用 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150324 How to Install Telegram Messenger Application on Linux","title":"如何在Linux上安装Telegram Messenger应用","tag":"201504","desc":""},"relativePath":"201504/20150324 How to Install Telegram Messenger Application on Linux.md","filePath":"[post].md"}'),g={name:"201504/20150324 How to Install Telegram Messenger Application on Linux.md"};function T(u,e,d,w,x,c){const l=m("Link");return p(),s("div",null,[e[17]||(e[17]=n('<h1 id="如何在linux上安装telegram-messenger应用" tabindex="-1">如何在Linux上安装Telegram Messenger应用 <a class="header-anchor" href="#如何在linux上安装telegram-messenger应用" aria-label="Permalink to “如何在Linux上安装Telegram Messenger应用”">​</a></h1><p>Telegram是和whatsapp类似的及时通讯应用。它有一个庞大的用户群，并且很多能和其他通讯应用区分开来的特性。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Install-Telegram-in-Linux.png" alt="在Linux上安装Telegram"> Telegram Messenger for Linux</p><p>这篇文章让你了解Telegram应用，以及在Linux Box上的详细安装命令。</p><h4 id="telegram的特性" tabindex="-1">Telegram的特性 <a class="header-anchor" href="#telegram的特性" aria-label="Permalink to “Telegram的特性”">​</a></h4><ul><li>支持移动设备</li><li>有桌面版本</li><li>第三方开发者可以访问Telegram的应用程序接口(API)。</li><li>支持Android, iphone/ipad, Windows Phone, Web-Version, PC, Mac 和 Linux。</li><li>以上应用支持高度加密和自销毁信息。</li><li>可以让你从多种设备和平台查看你的信息。</li><li>整体的处理和消息传送都非常快</li><li>为了安全和效率，在全球有分布式服务器</li><li>开放的API和自由协议</li><li>没有广告，没有认购费用。-永久免费</li><li>功能强大-没有媒体和聊天限制</li><li>多种安全措施使其免受黑客侵害</li><li>在群组中回复特定信息。使用@username提醒群组里的多个用户</li></ul><h4 id="为什么使用telegram" tabindex="-1">为什么使用Telegram? <a class="header-anchor" href="#为什么使用telegram" aria-label="Permalink to “为什么使用Telegram?”">​</a></h4><p>在像WhatsApp以及其他及时通讯应用都提供了几乎同样的功能的情况下，为什么要选择Telegram？</p><p>第三方开发者可以使用API这一点就足够了。更多PC的可用性意味着你不必再纠结在你的移动设备上打字，你可以使用你的PC，这样更具有可用性。</p><p>另外，支持连接远程地点，协作-多达200个成员的群组，在所有设备上同步，发送各种类型的文件，信息加密，自毁信息，在云上存储媒体，基于完全可用API构建自己的工具。</p><p><strong>测试环境</strong></p><p>我们使用Debian GNU/Linux, x86_64结构测试，所有的步骤都非常顺利。以下是我们的详细步骤。</p><h3 id="在linux上安装telegram-messenger" tabindex="-1">在Linux上安装Telegram Messenger <a class="header-anchor" href="#在linux上安装telegram-messenger" aria-label="Permalink to “在Linux上安装Telegram Messenger”">​</a></h3>',13)),i("p",null,[e[1]||(e[1]=t("首先去Telegram的官方网站，下载Linux系统版本的Telegram源码包(",-1)),a(l,{href:"https://tdesktop.com/linux"},{default:r(()=>[...e[0]||(e[0]=[t("tsetup.0.7.23.tar.xz",-1)])]),_:1}),e[2]||(e[2]=t(")，你也可以使用下面的wget命令直接下载。",-1))]),e[18]||(e[18]=n(`<pre><code># wget https://updates.tdesktop.com/tlinux/tsetup.0.7.23.tar.xz
</code></pre><p>下载好安装包后，解压安装包，并从当前目录进入解压后的文件夹。</p><pre><code># tar -xf tsetup.0.7.23.tar.xz 
# cd Telegram/
</code></pre><p>然后，如下所示，在命令行中执行二进制文件‘Telegram’.</p><pre><code># ./Telegram
</code></pre><ol><li>第一个界面， 点击 “START MESSAGING”.</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Start-Messaging.jpeg" alt="开始安装"> 开始安装</p><ol start="2"><li>输入你的手机号码，点击&quot;Next&quot;。如果在这之前你没有注册过Telegram，使用和之前输入相同的号码你会看到警告说你还没有Telegram账户。点击“Register Here”。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Register.png" alt="注册Telegram"> 注册Telegram</p><ol start="3"><li>提交你的手机号码之后，Telegram很快会给你发送一个验证码。你需要输入它。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Verfication-Code.png" alt="Telegram验证码"> Telegram验证码</p><ol start="4"><li>输入你的姓名，昵称并点击“SIGN UP”.</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Enter-Account-Details.jpeg" alt="输入账户详细信息"> 输入账户详细信息</p><ol start="5"><li>新建账户之后，我看到这个界面。一切准备就绪，尽管我对Telegram还不熟悉。这个界面真的很简洁。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Interface.jpeg" alt="Telegram界面"> Telegram界面</p><ol start="6"><li>点击新建联系人，输入他们的姓名和手机号码，完成后点击新建。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Add-New-Telegram-Contact.png" alt="新建Telegram联系人"> 新建Telegram联系人</p><ol start="7"><li>如果Telegram中还没有你输入的联系人，你会收到一个提示信息，当这个联系人加入Telegram的时候Telegram会通知你。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Contact-Notification.jpeg" alt="Telegram联系人提示"> Telegram联系人提示</p><ol start="8"><li><p>当联系人加入Telegram的时候，你会收到信息(类似弹出提示)显示[YOUR_CONTACT]加入了Telegram。</p></li><li><p>在Linux系统上正式的聊天窗口。很好的体验…</p></li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Contact-Join-Message.jpeg" alt="联系人加入Telegram消息"> 联系人加入Telegram消息</p><ol start="10"><li>同时，我试着在我的Android移动设备上发送信息，两者之间界面非常相似。</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Mobile-Interface.png" alt="移动版Telegram界面"> 移动版Telegram界面</p><ol start="11"><li>Telegram设置页面. 你有很多可以配置的选项.</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Telegram-Settings.png" alt="设置Telegram"> 设置Telegram</p><ol start="12"><li>关于Telegram.</li></ol><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/About-Telegram.jpeg" alt="关于Telegram"> 关于Telegram</p><h4 id="有趣的几点" tabindex="-1">有趣的几点 <a class="header-anchor" href="#有趣的几点" aria-label="Permalink to “有趣的几点”">​</a></h4><ul><li>Telegram使用MTProto移动协议</li><li>一开始在2013年(8月14号)发布iPhone版</li><li>惊人项目背后的人物:Pavel and Nikolai Durov..</li></ul><p>就是这些了。我还会为大家带来你们喜欢阅读的其它有趣文章。很高兴能代表Tecmint，感谢我们尊贵的读者以及使得我们通过不断的自我提升走到这里的批评者。保持联系！继续评论。如果你关注我们那就请分享吧。</p>`,30)),i("ul",null,[i("li",null,[a(l,{href:"https://telegram.org/"},{default:r(()=>[...e[3]||(e[3]=[t("https://telegram.org/",-1)])]),_:1})])]),e[19]||(e[19]=i("hr",null,null,-1)),i("p",null,[e[5]||(e[5]=t("via: ",-1)),a(l,{href:"http://www.tecmint.com/install-telegram-in-linux/"},{default:r(()=>[...e[4]||(e[4]=[t("http://www.tecmint.com/install-telegram-in-linux/",-1)])]),_:1})]),i("p",null,[e[9]||(e[9]=t("作者：",-1)),a(l,{href:"http://www.tecmint.com/author/avishek/"},{default:r(()=>[...e[6]||(e[6]=[t("Avishek Kumar",-1)])]),_:1}),e[10]||(e[10]=t(" 译者：",-1)),a(l,{href:"https://github.com/ictlyh"},{default:r(()=>[...e[7]||(e[7]=[t("ictlyh",-1)])]),_:1}),e[11]||(e[11]=t(" 校对：",-1)),a(l,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...e[8]||(e[8]=[t("Caroline",-1)])]),_:1})]),i("p",null,[e[14]||(e[14]=t("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[12]||(e[12]=[t("LCTT",-1)])]),_:1}),e[15]||(e[15]=t(" 原创翻译，",-1)),a(l,{href:"http://linux.cn/"},{default:r(()=>[...e[13]||(e[13]=[t("Linux中国",-1)])]),_:1}),e[16]||(e[16]=t(" 荣誉推出",-1))])])}const C=o(g,[["render",T]]);export{L as __pageData,C as default};
